<div class="mb-4"><h1 class="h3 section-title fw-bold">Reviews</h1><p class="text-secondary mb-0">Share feedback for completed cafeteria orders.</p></div>
<div class="row g-4"><div class="col-lg-5"><form class="surface-card p-4" action="<?= base_url('customer/reviews') ?>" method="post" data-confirm="Submit this review?" data-confirm-title="Submit review" data-confirm-label="Submit"><?= csrf_field() ?><h2 class="h5 section-title fw-bold">Write a review</h2><?php if ($orders): ?><div class="mb-3"><label class="form-label">Delivered order</label><select class="form-select" name="order_id" required><option value="">Select order</option><?php foreach ($orders as $order): ?><option value="<?= $order['id'] ?>"><?= esc($order['order_number']) ?> · <?= format_price($order['total']) ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Rating</label><select class="form-select" name="rating" required><option value="5">★★★★★ Excellent</option><option value="4">★★★★☆ Good</option><option value="3">★★★☆☆ Average</option><option value="2">★★☆☆☆ Poor</option><option value="1">★☆☆☆☆ Very poor</option></select></div><div class="mb-3"><label class="form-label">Comment</label><textarea class="form-control" name="comment" maxlength="1000"></textarea></div><button class="btn btn-primary w-100">Submit review</button><?php else: ?><div class="alert alert-light border mb-0">There are no delivered orders waiting for a review.</div><?php endif; ?></form></div><div class="col-lg-7"><div class="surface-card p-4"><h2 class="h5 section-title fw-bold">My feedback</h2><?php foreach ($reviews as $review): ?><div class="py-3 border-bottom"><div class="text-warning mb-1"><?= str_repeat('★',(int)$review['rating']) ?><?= str_repeat('☆',5-(int)$review['rating']) ?></div><p class="mb-1"><?= esc($review['comment'] ?: 'No written comment.') ?></p><small class="text-secondary"><?= esc(date('M j, Y',strtotime($review['created_at']))) ?></small></div><?php endforeach; ?><?php if (!$reviews): ?><?= view('components/empty', ['icon'=>'bi-star','message'=>'Your submitted reviews will appear here.']) ?><?php endif; ?></div></div></div>
